import type { PgDatabase, PgQueryResultHKT } from 'drizzle-orm/pg-core';
import type * as schema from './schema.js';

/** Drizzle database handle: node-postgres in the server, PGlite in tests. */
export type AppDb = PgDatabase<PgQueryResultHKT, typeof schema>;

/** Injection token of AppDb: `@Inject(DB) private readonly db: AppDb`. */
export const DB = Symbol('DB');
export const PG_POOL = Symbol('PG_POOL');

/** Folder of the SQL migrations generated by `pnpm --filter api db:generate`. */
export const MIGRATIONS_FOLDER = new URL('../../drizzle', import.meta.url);
